using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Text.Json;using System.Windows.Forms;using Observatory.Framework;using Observatory.Framework.Interfaces;using Observatory.Utils;
class Plugin:IObservatoryPlugin{public string Name=>"Synthetic Core";public string ShortName=>"Synthetic";public PluginUI PluginUI{get;}public Plugin(string[]headers,string[][]rows){var list=new ListView();foreach(var h in headers)list.Columns.Add(new(h));foreach(var r in rows)list.Items.Add(new(r));var panel=new Panel();panel.Controls.Add(list);PluginUI=new(){UI=panel,PluginUIType=PluginUI.UIType.Basic};}public byte[]ExportContent(string delimiter,ref string type)=>null;}
class Program{static void Main(){string[]headers={"Title","Count","Details"};string[][]rows={new[]{"Alpha","001","two\tfields"},new[]{"=1+2","9007199254740993","line1\nline2 & <π>"}};var folder=Path.Combine(Path.GetTempPath(),"core-export-source-"+Guid.NewGuid());Directory.CreateDirectory(folder);try{var p=new Plugin(headers,rows);SaveFileDialog.Target=Path.Combine(folder,"output.csv");ExportHandler.ExportCSV(p);var csv=File.ReadAllBytes(SaveFileDialog.Target);SaveFileDialog.Target=Path.Combine(folder,"output.xlsx");ExportHandler.ExportXlsx(p);using var zip=ZipFile.OpenRead(SaveFileDialog.Target);var entries=zip.Entries.ToDictionary(e=>e.FullName,e=>{using var s=new StreamReader(e.Open());return s.ReadToEnd();});Console.Write(JsonSerializer.Serialize(new{headers,rows,csv=Convert.ToBase64String(csv),xlsx=entries}));}finally{Directory.Delete(folder,true);}}}
